export function clamp(min: number, max: number, value: number) {
  return Math.min(max, Math.max(min, value));
}

//Linear Algebra
export type Vector3 = {
  x: number;
  y: number;
  z: number;
};

export function scale(vec: Vector3, scalar: number) {
  return {
    x: vec.x * scalar,
    y: vec.y * scalar,
    z: vec.z * scalar
  }
}

export function normalized(vec: Vector3) {
  if (!vec.x && !vec.y && !vec.z) {
    //if all values are zero, avoid division by 0(lines 20-22)
    return vec;
  }

  const mag = vec.x * vec.x + vec.y * vec.y + vec.z * vec.z;

  return {
    x: vec.x / mag,
    y: vec.y / mag,
    z: vec.z / mag
  };
}

export function add(vec1: Vector3, vec2: Vector3) {
  return {
    x: vec1.x + vec2.x,
    y: vec1.y + vec2.y,
    z: vec1.z + vec2.z
  };
}

export function subtract(vec1: Vector3, vec2: Vector3) {
  return {
    x: vec1.x - vec2.x,
    y: vec1.y - vec2.y,
    z: vec1.z - vec2.z
  };
}

export function dot(vec1: Vector3, vec2: Vector3) {
  return vec1.x * vec2.x + vec1.y * vec2.y + vec1.z * vec2.z;
}

export function cross(vec1: Vector3, vec2: Vector3) {
  return {
    x: vec1.y * vec2.z - vec1.z * vec2.y,
    y: vec1.z * vec2.x - vec1.x * vec2.z,
    z: vec1.x * vec2.y - vec1.y * vec2.x
  };
}


/*
  Matrices are stored in column major
*/

export function prettyPrintMat4x4(matrix: Float32Array) {
  console.log(`${matrix[0]}, ${matrix[1]}, ${matrix[2]}, ${matrix[3]},\n;
               ${matrix[4]}, ${matrix[5]}, ${matrix[6]}, ${matrix[7]},\n
               ${matrix[8]}, ${matrix[9]}, ${matrix[10]}, ${matrix[11]},\n
               ${matrix[12]}, ${matrix[13]}, ${matrix[14]}, ${matrix[15]}`);
}

export function matmul4x4(mat1: Float32Array, mat2: Float32Array) {
  let result = new Float32Array(16);
  for (let col2 = 0; col2 < 4; col2++) {
    for (let row1 = 0; row1 < 4; row1++) {
     result[col2 * 4 + row1] =
        mat1[row1]!      * mat2[col2 * 4]! +
        mat1[4 + row1]!  * mat2[col2 * 4 + 1]! +
        mat1[8 + row1]!  * mat2[col2 * 4 + 2]! +
        mat1[12 + row1]! * mat2[col2 * 4 + 3]!;
    }
  }

  return result;
}

export function translationMatrix(translation: Vector3) {
  const matrix = new Float32Array(16);

  matrix[0] = 1;
  matrix[5] = 1;
  matrix[10] = 1;
  matrix[15] = 1;

  matrix[12] = translation.x;
  matrix[13] = translation.y;
  matrix[14] = translation.z;

  return matrix;
}

export function scalingMatrix(scaling: Vector3) {
  const matrix = new Float32Array(16);

  matrix[0] = scaling.x;
  matrix[5] = scaling.y;
  matrix[10] = scaling.z;
  matrix[15] = 1;

  return matrix;
}

export function rollMatrix(angle: number) {
  const matrix = new Float32Array(16);

  matrix[0] = 1;
  matrix[15] = 1;

  matrix[5] = Math.cos(angle);
  matrix[6] = -Math.sin(angle);
  matrix[9] = Math.sin(angle);
  matrix[10] = Math.cos(angle);

  return matrix;
}

export function yawMatrix(angle: number) {
  const matrix = new Float32Array(16);

  matrix[5] = 1;
  matrix[15] = 1;

  matrix[0] = Math.cos(angle);
  matrix[2] = -Math.sin(angle);
  matrix[8] = Math.sin(angle);
  matrix[10] = Math.cos(angle);

  return matrix;
}

export function pitchMatrix(angle: number) {
  const matrix = new Float32Array(16);

  matrix[10] = 1;
  matrix[15] = 1;

  matrix[0] = Math.cos(angle);
  matrix[1] = -Math.sin(angle);
  matrix[4] = Math.sin(angle);
  matrix[5] = Math.cos(angle);

  return matrix;
}


